{"query":"

        fragment Money_BOGOS on MoneyV2 {
            currencyCode
            amount
        }



        fragment Product_BOGOS on Product {
            handle
            title
            id
            vendor
            productType
            tags
            isGiftCard
            collections (first: $numberCollections) {
                nodes {
                    id
                    title
                }
            }
        }

        fragment SellingPlanAllocation_BOGOS on SellingPlanAllocation {
            sellingPlan {
                id
            }
        }

        fragment CartLine_BOGOS on BaseCartLine {
            id
            viewKey
            quantity
            attributes {
                key
                value
            }
            cost {
                totalAmount {
                    ...Money_BOGOS
                }
                amountPerQuantity {
                    ...Money_BOGOS
                }
                compareAtAmountPerQuantity {
                    ...Money_BOGOS
                }
                subtotalAmount {
                    ...Money_BOGOS
                }
            }
            sellingPlanAllocation {
                ...SellingPlanAllocation_BOGOS
            }
            discountAllocations {
                ...DiscountAllocation_BOGOS
            }
            allDiscountAllocations: discountAllocations(lineLevelOnly: false) {
                ...DiscountAllocation_BOGOS
            }
            merchandise {
                ... on ProductVariant {
                    id
                    availableForSale
                    sku
                    taxable
                    weight
                    weightUnit
                    unitPrice {
                        ...Money_BOGOS
                    }
                    unitPriceMeasurement {
                        measuredType
                        quantityUnit
                        quantityValue
                        referenceUnit
                        referenceValue
                    }
                    compareAtPrice {
                        ...Money_BOGOS
                    }
                    price {
                        ...Money_BOGOS
                    }
                    requiresShipping
                    title
                    image {
                        id
                        url
                        altText
                        width
                        height
                    }
                    product {
                        ...Product_BOGOS
                    }
                    selectedOptions {
                        name
                        value
                    }
                }
            }
        }


        fragment CartDetail_BOGOS on Cart {
            id
            checkoutUrl
            totalQuantity
            upsell_codes: metafield (key: "upsell_codes", namespace: "$app") {
                value
            }
            buyerIdentity {
                countryCode
                email
                phone
            }
            lines(first: $numCartLines) {
                nodes {
                    ...CartLine_BOGOS
                    ... on ComponentizableCartLine {
                        lineComponents {
                            id
                        }
                    }
                }
            }
            cost {
                subtotalAmount {
                    ...Money_BOGOS
                }
                totalAmount {
                    ...Money_BOGOS
                }
            }
            note
            attributes {
                key
                value
            }
            discountCodes {
                code
                applicable
            }
        }


        fragment DiscountAllocation_BOGOS on CartDiscountAllocation {
            discountedAmount {
                ...Money_BOGOS
            }
            ...on CartAutomaticDiscountAllocation {
                title
            }
            ...on CartCustomDiscountAllocation {
                title
            }
            ...on CartCodeDiscountAllocation {
                code
            }
            targetType
            sourceDiscountApplication {
                __typename
                allocationMethod
                targetSelection
                targetType
                totalAllocatedAmount {
                    ...Money_BOGOS
                }
                value {
                    __typename
                    ...on MoneyV2 {
                        ...Money_BOGOS
                    }
                    ...on PricingPercentageValue {
                        percentage
                    }
                }
            }
        }


        query Cart_BOGOS (
            $cartId: ID!,
            $numCartLines: Int,
            $numberCollections: Int,
            $country: CountryCode,
            $language: LanguageCode
        ) @inContext(country: $country, language: $language) {
            cart(id: $cartId) {
                ...CartDetail_BOGOS
            }
        }
        ","variables":{"numCartLines":250,"numberCollections":250,"cartId":"gid://shopify/Cart/undefined","language":"EN","country":"US"}}

